import { S3Client, PutObjectCommand, ListObjectsV2Command, DeleteObjectsCommand } from '@aws-sdk/client-s3';
import { neon } from '@neondatabase/serverless';

function createR2Client(config) {
    return new S3Client({
        region: "auto",
        endpoint: `https://${config.accountId}.r2.cloudflarestorage.com`,
        credentials: {
            accessKeyId: config.accessKeyId,
            secretAccessKey: config.secretAccessKey
        }
    });
}
async function uploadToR2(client, bucket, key, body) {
    const buffer = Buffer.from(body, "utf-8");
    await client.send(new PutObjectCommand({
        Bucket: bucket,
        Key: key,
        Body: buffer,
        ContentType: "application/json"
    }));
    return buffer.length;
}
async function listPrefixes(client, bucket, prefix) {
    const prefixes = [];
    let continuationToken;
    do {
        const response = await client.send(new ListObjectsV2Command({
            Bucket: bucket,
            Prefix: prefix,
            Delimiter: "/",
            ContinuationToken: continuationToken
        }));
        if (response.CommonPrefixes) {
            for (const cp of response.CommonPrefixes){
                if (cp.Prefix) prefixes.push(cp.Prefix);
            }
        }
        continuationToken = response.NextContinuationToken;
    }while (continuationToken)
    return prefixes;
}
async function listAllKeys(client, bucket, prefix) {
    const keys = [];
    let continuationToken;
    do {
        const response = await client.send(new ListObjectsV2Command({
            Bucket: bucket,
            Prefix: prefix,
            ContinuationToken: continuationToken
        }));
        if (response.Contents) {
            for (const obj of response.Contents){
                if (obj.Key) keys.push(obj.Key);
            }
        }
        continuationToken = response.NextContinuationToken;
    }while (continuationToken)
    return keys;
}
async function deleteKeys(client, bucket, keys) {
    // DeleteObjects supports up to 1000 keys per call
    for(let i = 0; i < keys.length; i += 1000){
        const batch = keys.slice(i, i + 1000);
        await client.send(new DeleteObjectsCommand({
            Bucket: bucket,
            Delete: {
                Objects: batch.map((key)=>({
                        Key: key
                    })),
                Quiet: true
            }
        }));
    }
}

async function discoverTables(databaseUrl) {
    const sql = neon(databaseUrl);
    const rows = await sql`
    SELECT table_name
    FROM information_schema.tables
    WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
    ORDER BY table_name
  `;
    return rows.map((r)=>r.table_name);
}
async function getTableSchema(databaseUrl, tableName) {
    const sql = neon(databaseUrl);
    const columns = await sql`
    SELECT column_name, data_type, is_nullable, column_default, udt_name, ordinal_position
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = ${tableName}
    ORDER BY ordinal_position
  `;
    const constraints = await sql`
    SELECT conname, pg_get_constraintdef(oid) AS definition
    FROM pg_constraint
    WHERE conrelid = ${`public.${tableName}`}::regclass
  `;
    const indexes = await sql`
    SELECT indexname, indexdef
    FROM pg_indexes
    WHERE schemaname = 'public' AND tablename = ${tableName}
  `;
    return {
        tableName,
        columns,
        constraints,
        indexes
    };
}
async function exportTableData(databaseUrl, tableName) {
    const sql = neon(databaseUrl);
    // neon() only supports tagged templates; use sql.query() for dynamic table names
    const rows = await sql.query(`SELECT * FROM "${tableName}"`);
    const lines = rows.map((row)=>JSON.stringify(row));
    return {
        jsonl: lines.join("\n"),
        rowCount: rows.length
    };
}

async function cleanupOldBackups(client, bucket, appName, retentionDays) {
    const prefix = `${appName}/`;
    const datePrefixes = await listPrefixes(client, bucket, prefix);
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - retentionDays);
    const cutoffStr = cutoff.toISOString().slice(0, 10); // YYYY-MM-DD
    const deleted = [];
    for (const datePrefix of datePrefixes){
        // Extract date from prefix like "research-thera/2026-03-30/"
        const parts = datePrefix.replace(prefix, "").replace(/\/$/, "");
        if (parts < cutoffStr) {
            const keys = await listAllKeys(client, bucket, datePrefix);
            if (keys.length > 0) {
                await deleteKeys(client, bucket, keys);
                deleted.push(datePrefix);
            }
        }
    }
    return deleted;
}

const PACKAGE_VERSION = "0.1.0";
async function runBackup(config) {
    const startedAt = new Date();
    const dateStr = startedAt.toISOString().slice(0, 10);
    const r2 = createR2Client(config.r2);
    const bucket = config.r2.bucketName;
    const prefix = `${config.appName}/${dateStr}`;
    const tables = {};
    let overallStatus = "complete";
    try {
        const tableNames = await discoverTables(config.databaseUrl);
        console.log(`[backup] ${config.appName}: found ${tableNames.length} tables`);
        for (const tableName of tableNames){
            const elapsed = Date.now() - startedAt.getTime();
            if (elapsed > config.maxDurationMs * 0.8) {
                console.log(`[backup] timeout approaching, skipping remaining tables`);
                tables[tableName] = {
                    tableName,
                    rowCount: 0,
                    sizeBytes: 0,
                    status: "skipped_timeout"
                };
                overallStatus = "partial";
                continue;
            }
            try {
                // Export schema
                const schema = await getTableSchema(config.databaseUrl, tableName);
                const schemaJson = JSON.stringify(schema, null, 2);
                await uploadToR2(r2, bucket, `${prefix}/schema/${tableName}.json`, schemaJson);
                // Export data
                const { jsonl, rowCount } = await exportTableData(config.databaseUrl, tableName);
                let sizeBytes = 0;
                if (jsonl.length > 0) {
                    sizeBytes = await uploadToR2(r2, bucket, `${prefix}/data/${tableName}.jsonl`, jsonl);
                }
                tables[tableName] = {
                    tableName,
                    rowCount,
                    sizeBytes,
                    status: "complete"
                };
                console.log(`[backup] ${tableName}: ${rowCount} rows, ${sizeBytes} bytes`);
            } catch (err) {
                const message = err instanceof Error ? err.message : String(err);
                tables[tableName] = {
                    tableName,
                    rowCount: 0,
                    sizeBytes: 0,
                    status: "failed",
                    error: message
                };
                overallStatus = "partial";
                console.error(`[backup] ${tableName} failed: ${message}`);
            }
        }
    } catch (err) {
        overallStatus = "failed";
        console.error(`[backup] discovery failed: ${err}`);
    }
    const completedAt = new Date();
    const manifest = {
        app: config.appName,
        date: dateStr,
        startedAt: startedAt.toISOString(),
        completedAt: completedAt.toISOString(),
        status: overallStatus,
        tables,
        durationMs: completedAt.getTime() - startedAt.getTime(),
        packageVersion: PACKAGE_VERSION
    };
    // Upload manifest
    try {
        await uploadToR2(r2, bucket, `${prefix}/manifest.json`, JSON.stringify(manifest, null, 2));
    } catch (err) {
        console.error(`[backup] manifest upload failed: ${err}`);
    }
    // Retention cleanup
    try {
        const deleted = await cleanupOldBackups(r2, bucket, config.appName, config.retentionDays);
        if (deleted.length > 0) {
            console.log(`[backup] cleaned up ${deleted.length} old backups`);
        }
    } catch (err) {
        console.error(`[backup] retention cleanup failed: ${err}`);
    }
    return manifest;
}

function verifyCronSecret(request) {
    const authHeader = request.headers.get("authorization");
    const cronSecret = process.env.CRON_SECRET;
    if (!cronSecret) {
        return new Response(JSON.stringify({
            error: "CRON_SECRET not configured"
        }), {
            status: 500,
            headers: {
                "Content-Type": "application/json"
            }
        });
    }
    if (authHeader !== `Bearer ${cronSecret}`) {
        return new Response(JSON.stringify({
            error: "Unauthorized"
        }), {
            status: 401,
            headers: {
                "Content-Type": "application/json"
            }
        });
    }
    return null;
}

export { runBackup, verifyCronSecret };
